from abc import ABC, abstractmethod

class AudioPlayer(ABC):
    @abstractmethod
    def playAudio(self):
        pass

class VideoPlayer(ABC):
    @abstractmethod
    def playVideo(self):
        pass

class MediaCenter(AudioPlayer, VideoPlayer):
    def __init__(self, filename):
        self.filename = filename

    def playAudio(self):
        print("Audio file detected: Playing with 128kbps quality")

    def playVideo(self):
        print("Video file detected: Playing at 1080p resolution")

filename = input().strip()

audio_extensions = {'.mp3', '.wav', '.aac', '.flac', '.ogg'}
video_extensions = {'.mp4', '.avi', '.mkv', '.mov', '.wmv'}

ext = '.' + filename.rsplit('.', 1)[-1].lower() if '.' in filename else ''

media = MediaCenter(filename)

if ext in audio_extensions:
    media.playAudio()
elif ext in video_extensions:
    media.playVideo()
